export function inspectPersonDate(m,i){const base=basicInspectPersonDate(m,i),date=dateFor(m,i)?.date;return date?{...base,label:date.travel?(date.travel.returning?'Traveling home':'Traveling to '+date.travel.destination.name):date.localMovement?.personIds.includes(pid(m,i))?'Walking in the date neighborhood':base.label,phase:date.phase,globalPlace:clone(date.globalPlace??null),world:clone(date.world??null),datePosition:clone(date.worldPositions?.[pid(m,i)]??{x:0,z:0}),travel:date.travel?{mode:date.travel.mode,etaMinute:date.travel.etaMinute,progress:date.travel.progress}:null}:null;}
export function recordDateInterval(m,i,activity,start,duration){const row=dateFor(m,i),date=row?.date;if(!date||date.attendance?.available===false)return;if(date.travel&&['traveling','traveling-home'].includes(date.phase)){if(activity!==8)return;const t=date.travel,dt=Math.max(0,Math.min(start+duration,t.etaMinute)-Math.max(start,t.departedMinute));t.progressMinutes[i]=Math.min(t.durationMinutes,(t.progressMinutes[i]??0)+dt);m.totals.dateTravelPersonMinutes=(m.totals.dateTravelPersonMinutes??0)+dt;date.travelPersonMinutes=(date.travelPersonMinutes??0)+dt;return;}if(date.localMovement){const move=date.localMovement,id=pid(m,i);if(move.personIds.includes(id)&&activity===6){const dt=Math.max(0,Math.min(start+duration,move.etaMinute)-Math.max(start,move.startedMinute));move.progressMinutes[id]=Math.min(move.durationMinutes,(move.progressMinutes[id]??0)+dt);}return;}basicRecordDateInterval(m,i,activity,start,duration);}
function advanceDates(m,home,start,end){const date=home.systems?.dates?.active;if(!date)return;refreshDateHorizon(m,date,end);if(date.attendance?.available===false)return;if(date.travel){const t=date.travel,elapsed=Math.min(...date.indices.map(i=>t.progressMinutes[i]??0)),stopped=(t.stopIntervals??[]).reduce((sum,s)=>sum+Math.max(0,Math.min(end,s.untilMinute)-Math.max(t.departedMinute,s.startedMinute)),0),previous=t.progress??0;t.progress=Math.min(1,Math.max(previous,(elapsed-stopped)/Math.max(.1,t.motionDurationMinutes??t.durationMinutes)));date.distanceMetersMoved=(date.distanceMetersMoved??0)+Math.max(0,t.progress-previous)*t.distanceMeters;t.geographicPosition=routeGeographicPoint(t,t.progress);if(date.indices.every(i=>(t.progressMinutes[i]??0)>=t.durationMinutes-1e-7)&&end>=t.etaMinute-1e-7){date.journeys??=[];date.journeys.push({mode:t.mode,source:t.source,approximate:t.approximate,departedMinute:t.departedMinute,arrivedMinute:end,durationMinutes:t.durationMinutes,distanceMeters:t.distanceMeters,cost:t.paidCost,returning:t.returning});date.journeys=date.journeys.slice(-16);if(t.returning){endDate(m,home,{reason:'Actual shared return journey completed'});return;}date.venue=clone(t.destination);initializeWorld(date,date.venue);setCityAnchor(m,date,date.venue);date.arrivedMinute=end;date.phase='arrived';date.travel=null;if(date.itinerary[date.currentStop])Object.assign(date.itinerary[date.currentStop],{status:'visited',arrivedMinute:end});dateAdapters.memory?.recordMoment?.(m,home,date,{type:'arrival',text:'Arrived at '+date.venue.name,place:date.place},end);event(m,home,'HOUSE_DATE_ARRIVED',{dateId:date.id,personIds:date.personIds,venueId:date.venue.id});}}if(date.localMovement){const move=date.localMovement;for(const id of move.personIds){const progress=Math.min(1,(move.progressMinutes[id]??0)/move.durationMinutes);date.worldPositions[id]={x:move.from[id].x+(move.to.x-move.from[id].x)*progress,z:move.from[id].z+(move.to.z-move.from[id].z)*progress};}if(move.personIds.every(id=>(move.progressMinutes[id]??0)>=move.durationMinutes-1e-7)){event(m,home,'HOUSE_DATE_WALK_ARRIVED',{dateId:date.id,personIds:move.personIds,x:move.to.x,z:move.to.z});dateAdapters.memory?.recordMoment?.(m,home,date,{type:'walk-arrived',text:'Walked to a selected neighborhood point',activity:'walk'},end);date.localMovement=null;}}if(dateAdapters.experience&&['date','traveling','traveling-home'].includes(date.phase)){const result=dateAdapters.experience.advance?.(m,home,date,start,end,contextFor(m,home,date));for(const effect of result?.effects??[])applyExperienceEffects(m,home,date,effect,effect.id);for(const e of result?.events??[]){if(e.requiresReroute){date.venue.closed=true;date.venue.closureSource='Seeded date-world event, not observed opening hours';if(date.activity&&['eat','coffee','dessert','picnic'].includes(date.activity.type))interruptDateActivity(m,home,date,'The simulated venue closed');}if(e.type==='festival'||e.text?.includes('street festival')){date.venue.activities??=[];if(!date.venue.activities.includes('festival'))date.venue.activities.push('festival');}dateAdapters.memory?.recordMoment?.(m,home,date,e,e.minute??end);}}for(const effect of date.pendingEffects??[])if(effect.applyAt<=end){applyExperienceEffects(m,home,date,effect.effects,effect.id);dateAdapters.memory?.recordMoment?.(m,home,date,{id:effect.id+':outcome',type:'travel-stop-completed',activity:effect.activity,text:'Completed the shared '+effect.activity+' stop'},end);}date.pendingEffects=(date.pendingEffects??[]).filter(e=>e.applyAt>end);dateAdapters.memory?.sample?.(m,home,date,end);refreshDateHorizon(m,date,end);}
export function inspectDateSystem(m,home){const result=basicInspectDateSystem(m,home),date=home.systems?.dates?.active;if(date){delete result.active.preferences;result.venues=date.globalPlace?(clone(date.nearbyPlaces??date.itinerary.map(s=>s.place))):result.venues;result.active.experience=dateAdapters.experience?.inspect?.(m,home,date)??null;result.active.world=clone(date.world??null);result.active.globalPlace=clone(date.globalPlace??null);result.active.itinerary=clone(date.itinerary??[]);result.active.travel=date.travel?{...clone(date.travel),elapsedMinutes:Math.min(...date.indices.map(i=>date.travel.progressMinutes[i]??0)),remainingMinutes:Math.max(0,date.travel.etaMinute-m.minute)}:null;for(const p of result.active.people)p.datePosition=clone(date.worldPositions?.[p.id]??{x:0,z:0});}if(date?.venue.closed)for(const a of result.activities)if(['eat','coffee','dessert','picnic'].includes(a.id)){a.available=false;a.reason='This simulated venue is closed; choose another stop';a.recovery={type:'venue',label:'Choose another venue',requiresSelection:true};}result.origin=clone(date?.origin??home.systems?.dates?.origin??(m.worldOrigin?homeGeographicOrigin(m,home,m.worldOrigin):null));result.openEnded=true;result.endPolicy='Dates finish only through an explicit Complete date or return-home command; partner leave suggestions remain advisory.';result.budget=m.households.savings[hOf(m,home)];result.knownPreferences=knownDatePreferences(m,home,date);result.memories=dateAdapters.memory?.inspect?.(m,home)??null;return result;}
export function validateDateSystem(m,home){basicValidateDateSystem(m,home);const date=home.systems?.dates?.active;if(date){check(date.completedActivityCount===undefined||Number.isSafeInteger(date.completedActivityCount)&&date.completedActivityCount>=date.completedActivities.length,'Invalid total date activity count');check(date.requestedExtraMinutes===undefined||Number.isFinite(date.requestedExtraMinutes)&&date.requestedExtraMinutes>=0&&date.requestedExtraMinutes<=7*1440,'Invalid suggested date extension');check((date.completedActivities?.length??0)<=64,'Date activity history retention exceeded');check(DATE_PHASES.includes(date.phase),'Invalid date phase');if(date.globalPlace)createDatePlace(date.globalPlace);if(date.worldPositions)for(const p of Object.values(date.worldPositions))check([p.x,p.z].every(Number.isFinite)&&Math.hypot(p.x,p.z)<=600,'Invalid date-local actor position');if(date.travel)check(['drive','walk'].includes(date.travel.mode)&&Number.isFinite(date.travel.durationMinutes)&&date.travel.durationMinutes>0&&date.travel.durationMinutes<=7*1440&&Math.abs(date.travel.etaMinute-date.travel.departedMinute-date.travel.durationMinutes)<1e-6&&date.indices.every(i=>Number.isFinite(date.travel.progressMinutes[i])&&date.travel.progressMinutes[i]>=0&&date.travel.progressMinutes[i]<=date.travel.durationMinutes),'Invalid actual date travel');if(date.itinerary)check(date.itinerary.length<=8,'Date itinerary exceeds8stops');validateDateAdventureState(m,date);dateAdapters.experience?.validate?.(m,home,date);}dateAdapters.memory?.validate?.(m,home);}
export function createDateSystem(){const basic=basicCreateDateSystem();return{...basic,command:applyDateCommand,inspect:inspectDateSystem,validate:validateDateSystem,prepare(m,home){const date=home.systems?.dates?.active;if(!date)return;upgradeDateState(m,home,date);if(date.indices.some(i=>['bladder','hunger','energy'].some(need=>Number.isFinite(m.people[need]?.[i])&&m.people[need][i]<=10))){cancelDateAction(m,home,date,'Taking care of urgent basic needs');endDate(m,home,{reason:'Returned home for urgent basic needs',returnPeople:true});return;}if(!recoverStalledDate(m,home,date))return;date.financeSequence??=0;date.appliedEffects??=[];date.itinerary??=[];if(!date.experience)dateAdapters.experience?.initialize?.(m,home,date);basic.prepare(m,home);if(date.phase==='arrived'&&date.attendance?.available!==false){date.phase='date';if(date.untilMinute-m.minute>=30)beginActivity(m,home,date,'talk');}},advance:(m,home,{startMinute,endMinute})=>advanceDates(m,home,startMinute,endMinute)};}

configureDateSystemAdapters({experience:{initialize:(m,home,date)=>createDateExperience({date,minute:m.minute}),advance:(m,home,date,start,end,context)=>advanceDateExperience(date,{...context,minute:end}),command:(m,home,date,input,context)=>applyDateExperienceCommand(date,input,context),inspect:(m,home,date)=>inspectDateExperience(date),validate:(m,home,date)=>validateDateExperience(date)}});

function knownDatePreferences(m,home,date){const known=home.systems?.dates?.knowledge??{},ids=[...new Set([...Object.keys(known),...(date?.personIds??[])])];return Object.fromEntries(ids.map(id=>{const values=date?.preferences?.[id]??datePreferencesFor(m,id,known[id]?.learned??[]),discoveries=[...new Set([...(known[id]?.discoveries??[]),...(date?.experience?.discoveries??[])])];return[id,inspectDatePreferences(values,discoveries)];}));}

configureDateSystemAdapters({memory:{started:beginDateMemory,sample:sampleDateMemory,activityCompleted:(m,home,date,a)=>recordDateMoment(m,home,date,{id:a.id,type:'activity-completed',text:a.label+' at '+date.place.name,activity:a.type,place:date.place},a.completedMinute),recordMoment:recordDateMoment,ended:(m,home,date)=>{date.totalCost=date.cost;return finishDateMemory(m,home,date,m.minute);},command:applyDateMemoryCommand,inspect:inspectDateMemories,validate:validateDateMemories}});

function interruptDateActivity(m,home,date,reason){if(!date.activity)return;date.interruptedActivities??=[];date.interruptedActivities.push({...clone(date.activity),endedMinute:m.minute,reason,noCompletionGranted:true,refund:0});date.interruptedActivities=date.interruptedActivities.slice(-8);event(m,home,'HOUSE_DATE_ACTIVITY_INTERRUPTED',{dateId:date.id,personIds:date.personIds,activity:date.activity.type,reason});dateAdapters.memory?.recordMoment?.(m,home,date,{type:'activity-interrupted',text:reason,activity:date.activity.type},m.minute);date.activity=null;}

function dateProgressionHome(m,home,i){const h=m.people.household[i];if(m.houses?.homes?.[h])return m.houses.homes[h];check(Object.keys(m.houses?.homes??{}).length<128,'Household skill retention limit reached');const own=getHouseState(m,h);m.houses.homes[h]=own;return own;}

function routeGeographicPoint(travel,progress){const points=travel.geometry??[];if(!points.length)return null;if(points.length===1)return clone(points[0]);const distances=points.slice(1).map((p,i)=>haversineMeters(points[i],p)),total=distances.reduce((a,b)=>a+b,0);let target=total*progress;for(let i=0;i<distances.length;i++){if(target<=distances[i]||i===distances.length-1){const f=distances[i]?Math.max(0,Math.min(1,target/distances[i])):1;return{lat:points[i].lat+(points[i+1].lat-points[i].lat)*f,lng:points[i].lng+(points[i+1].lng-points[i].lng)*f};}target-=distances[i];}return clone(points.at(-1));}

function upgradeDateState(m,home,date){if(date.venue?.globalPlace){date.venue.x=Math.fround(date.venue.x);date.venue.z=Math.fround(date.venue.z);}if(date.phase==='together'||!date.phase)date.phase='date';date.durationMinutes??=Math.max(30,Math.min(1440,date.untilMinute-date.startedMinute));date.completedActivities??=[];date.completedActivityCount??=date.completedActivities.length;date.cancelSequence??=0;if(!date.venue?.globalPlace&&date.venue&&(!date.venue.activities||Object.keys(DATE_ACTIVITIES).every(id=>date.venue.activities.includes(id))))date.venue.activities=venueActivityIds(date.venue.kind);refreshDateHorizon(m,date);date.origin??=clone(home.systems.dates.origin??m.worldOrigin??null);date.financeSequence??=0;date.movementSequence??=0;date.appliedEffects??=[];date.itinerary??=[{place:clone(date.globalPlace??date.venue),status:'visited',arrivedMinute:date.startedMinute}];date.currentStop??=0;if(!date.worldPositions)initializeWorld(date,date.venue);date.preferences??=Object.fromEntries(date.personIds.map(id=>[id,datePreferencesFor(m,id,home.systems.dates.knowledge?.[id]?.learned??[])]));if(!date.experience)dateAdapters.experience?.initialize?.(m,home,date);if(!home.systems.dates.memories?.records.some(r=>r.id===date.id))dateAdapters.memory?.started?.(m,home,date,m.minute);}

function validateDateAdventureState(m,date){check((date.interruptedGames?.length??0)<=8&&(date.interruptedMoves?.length??0)<=8&&(date.interruptedTravel?.length??0)<=4,'Interrupted date action retention exceeded');for(const row of date.interruptedGames??[])check(typeof row.id==='string'&&['arcade','karaoke','miniGolf'].includes(row.type)&&Number.isInteger(row.inputCount)&&row.inputCount>=0&&row.inputCount<=8&&row.noCompletionGranted===true&&Number.isFinite(row.endedMinute)&&row.endedMinute<=m.minute,'Invalid interrupted date game');if(date.minigameAttemptSequence!==undefined)check(Number.isSafeInteger(date.minigameAttemptSequence)&&date.minigameAttemptSequence>=0,'Invalid date game attempt sequence');check((date.appliedEffects?.length??0)<=256&&(date.pendingEffects?.length??0)<=128&&(date.journeys?.length??0)<=16,'Date adventure retention exceeded');if(date.world?.positions&&date.worldPositions)for(const id of date.personIds)check(date.world.positions[id]?.x===date.worldPositions[id]?.x&&date.world.positions[id]?.z===date.worldPositions[id]?.z,'Date position projections differ');if(date.origin)check(validDateCoordinates(date.origin),'Invalid saved home origin');if(date.travel){check(date.travel.departedMinute<=m.minute&&date.indices.every(i=>date.travel.progressMinutes[i]<=m.minute-date.travel.departedMinute+1e-6),'Date travel cannot contain future attendance');check((date.travel.stopIntervals?.length??0)<=128,'Too many date travel stops');for(const stop of date.travel.stopIntervals??[])check(Number.isFinite(stop.startedMinute)&&Number.isFinite(stop.untilMinute)&&stop.untilMinute>=stop.startedMinute&&stop.startedMinute>=date.travel.departedMinute,'Invalid date stop time');}if(date.localMovement){const move=date.localMovement;check(Array.isArray(move.personIds)&&move.personIds.length>=1&&move.personIds.length<=2&&new Set(move.personIds).size===move.personIds.length&&move.personIds.every(id=>date.personIds.includes(id))&&Number.isFinite(move.startedMinute)&&move.startedMinute<=m.minute&&Number.isFinite(move.durationMinutes)&&move.durationMinutes>0&&move.durationMinutes<=120&&Math.abs(move.etaMinute-move.startedMinute-move.durationMinutes)<1e-6&&[move.to.x,move.to.z].every(Number.isFinite)&&Math.hypot(move.to.x,move.to.z)<=500,'Invalid date neighborhood walk');for(const id of move.personIds)check(Number.isFinite(move.progressMinutes[id])&&move.progressMinutes[id]>=0&&move.progressMinutes[id]<=move.durationMinutes&&move.progressMinutes[id]<=m.minute-move.startedMinute+1e-6&&[move.from[id]?.x,move.from[id]?.z].every(Number.isFinite),'Invalid actual walking attendance');}for(const effect of date.pendingEffects??[])check(typeof effect.id==='string'&&effect.id.length<=220&&Number.isFinite(effect.applyAt)&&effect.applyAt>=date.startedMinute,'Invalid delayed date outcome');}

function pointGeographic(origin,x,z){return{lat:origin.lat-z/110540,lng:origin.lng+x/(111320*Math.cos(origin.lat*Math.PI/180))};}
function homeGeographicOrigin(m,home,worldOrigin){const anchor=homeAnchor(m,home);return pointGeographic(worldOrigin,anchor.x,anchor.z);}
